class Solution {
    public boolean isConsecutive(int[] nums) {
        Set<Integer> st = new HashSet<>();
        int mn = Integer.MAX_VALUE, mx = Integer.MIN_VALUE;
        for (int x : nums) {
            st.add(x);
            mn = Math.min(mn, x);
            mx = Math.max(mx, x);
        }
        return st.size() == nums.length && mx - mn == nums.length - 1;
    }
};

