var isConsecutive = function(nums) {
    const st = new Set(nums);
    if (st.size !== nums.length) return false;
    let mn = Infinity, mx = -Infinity;
    for (const x of nums) {
        mn = Math.min(mn, x);
        mx = Math.max(mx, x);
    }
    return mx - mn === nums.length - 1;
};
